package com.worklink.config;
import com.worklink.entity.*;import com.worklink.repository.*;import org.springframework.boot.CommandLineRunner;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.context.annotation.*;
@Configuration @ConditionalOnProperty(prefix="worklink.catalog-seed",name="enabled",havingValue="true",matchIfMissing=true) public class CatalogSeedConfig {@Bean CommandLineRunner catalogSeed(CategoryRepository categories,SkillRepository skills){return a->{String[] c={"Web Development","Mobile Development","UI/UX Design","Data Science","Machine Learning","Software Testing","Cloud & DevOps","Content Writing","Digital Marketing"};for(String n:c)if(!categories.existsByNameIgnoreCase(n))categories.save(new Category(n,"WorkLink catalog category"));String[] s={"Java","JavaScript","TypeScript","React","Angular","Node.js","Spring Boot","Python","SQL","PostgreSQL","MongoDB","UI/UX Design","Figma","Docker","AWS","Git"};for(String n:s)if(!skills.existsByNameIgnoreCase(n))skills.save(new Skill(n,null));};}}
